function sideLeftNotes(moved, repriced, session, items) {
    const notes = [];
    for (const side of /** @type {const} */ (['cap', 'garment'])) {
        if (moved[side].length === 0) continue;
        if ([...repriced.values()].some(g => g.isCap === (side === 'cap'))) continue;
